const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const etna = ee.Geometry.Point([14.999, 37.751]); // Mount Etna coordinates
  const date = '2021-02-23';
  const startTime = '2021-02-23T00:00:00'; // Local time is UTC+1, so 1:37 am = 00:37 UTC
  const endTime = '2021-02-23T01:00:00';   // Narrow window around the time

  // 2. Data Acquisition - Try VIIRS for nighttime plume detection
  let collection = ee.ImageCollection('NOAA/VIIRS/001/VNP02IMG')
    .filterBounds(etna)
    .filterDate(startTime, endTime);

  const count = collection.size().getInfo();
  console.log(`VIIRS Images found: ${count}`);

  if (count === 0) {
    // Try MODIS as fallback
    collection = ee.ImageCollection('MODIS/061/MYD021KM')
      .filterBounds(etna)
      .filterDate(startTime, endTime);
    const modisCount = collection.size().getInfo();
    console.log(`MODIS Images found: ${modisCount}`);

    if (modisCount === 0) {
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // 3. Processing - Get the first image and check for valid pixels
  const image = collection.first();

  // Use M12 band (3.7μm) which is good for nighttime thermal detection
  const thermalBand = 'M12';
  const plumeImage = image.select(thermalBand);

  // Check pixel count around Etna
  const buffer = etna.buffer(50000); // 50km buffer around Etna
  const pixelCount = plumeImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  }).get(thermalBand).getInfo();

  console.log(`Valid pixels in 50km buffer: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Analyze plume direction
  // Create sectors to detect plume direction
  const westSector = etna.buffer(30000).intersection(
    ee.Geometry.Polygon([
      [14.499, 37.451], [14.499, 38.051], [14.999, 38.051], [14.999, 37.451]
    ])
  );

  const eastSector = etna.buffer(30000).intersection(
    ee.Geometry.Polygon([
      [14.999, 37.451], [14.999, 38.051], [15.499, 38.051], [15.499, 37.451]
    ])
  );

  // Calculate mean brightness temperature in each sector
  const westTemp = plumeImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: westSector,
    scale: 1000,
    maxPixels: 1e9
  }).get(thermalBand).getInfo();

  const eastTemp = plumeImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: eastSector,
    scale: 1000,
    maxPixels: 1e9
  }).get(thermalBand).getInfo();

  console.log(`West sector temp: ${westTemp ? westTemp.toFixed(2) : 'null'}`);
  console.log(`East sector temp: ${eastTemp ? eastTemp.toFixed(2) : 'null'}`);

  // 5. Validation & Final Answer
  if (westTemp === null || eastTemp === null || isNaN(westTemp) || isNaN(eastTemp)) {
    console.log("<answer>C3</answer>");
  } else {
    // If west sector is significantly warmer (plume signature), answer Yes
    const tempDiff = westTemp - eastTemp;
    console.log(`Temperature difference (W-E): ${tempDiff.toFixed(2)}`);

    if (tempDiff > 2.0) { // Threshold for plume detection
      console.log("<answer>A</answer>");
    } else {
      console.log("<answer>B</answer>");
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
